import React, { HTMLProps, useCallback, useEffect, useMemo, useState } from 'react';
import { observer } from 'mobx-react-lite';
import MdEditor, { Plugins } from 'react-markdown-editor-lite';
import 'react-markdown-editor-lite/lib/index.css';
import Store from './store';
import styles from './style.module.less';
import ViewMarkdown from '../ViewMarkdown';

const PLUGINS = undefined;
MdEditor.use(Plugins.TabInsert, {
  tabMapValue: 2, // note that 1 means a '\t' instead of ' '.
});

export interface EditMarkdownProps {
    style?: React.CSSProperties;
    className?: string;
    value?: string;
    onChange?: (val: string) => void;
}

const EditMarkdown = ({ value, onChange, ...props }: EditMarkdownProps) => {

    const [store] = useState(() => new Store());

    const renderHTML = useCallback((text) => {
        return (
            <ViewMarkdown text={text} isOutline={false} />
        )
    },[])


    return (
        <div className={styles.component} style={{ height: '100%' }} {...props} >
            <MdEditor
                ref={node => (store.mdEditor = node || undefined)}
                value={value}
                style={{ height: '100%', width: '100%', minHeight: 200 }}
                renderHTML={renderHTML}
                plugins={PLUGINS}
                config={{
                    view: {
                        menu: true,
                        md: true,
                        html: true,
                        fullScreen: true,
                        hideMenu: true,
                    },
                    table: {
                        maxRow: 5,
                        maxCol: 6,
                    },
                    // imageUrl: 'https://octodex.github.com/images/minion.png',
                    syncScrollMode: ['leftFollowRight', 'rightFollowLeft'],
                }}
                onChange={(it) => {
                    if(onChange) onChange(it.text);
                }}
                onImageUpload={store.handleImageUpload}
                // onFocus={e => console.log('focus', e)}
                // onBlur={e => console.log('blur', e)}
                onCustomImageUpload={store.onCustomImageUpload}
            />
        </div>
    )
}

export default observer(EditMarkdown);