import { Button, Input, Message, Radio, Space, Upload } from "@arco-design/web-react";
import UploadImg from "@system/UploadImg";
import React, { useContext, useState } from "react";


interface CustomUploadProps {
  onClose: () => void;
  onSubmit: (url: string) => void;
}

const CustomUpload = (props: CustomUploadProps) => {

  
  const [type, setType] = useState<"url" | "file">("url");
  const [fileUrl, setFileUrl] = useState<string>("");
  const [url, setUrl] = useState<string>("");

  return (
      <div>
        <div className="text-xl font-bold text-center">
          添加图片
        </div>
        <Radio.Group value={type} onChange={setType} className="my-8">
          <Radio value="file">
              {({ checked }) => {
                return (
                  <Button tabIndex={-1} shape='round' type={checked ? 'primary' : 'default'}>
                    上传图片
                  </Button>
                );
              }}
          </Radio>
          <Radio value="url">
              {({ checked }) => {
                return (
                  <Button tabIndex={-1} shape='round' type={checked ? 'primary' : 'default'}>
                    使用外链
                  </Button>
                );
              }}
          </Radio>
        </Radio.Group>
        {type == 'file' && (
          <UploadImg
            listType="picture-list"
            drag
            value={fileUrl}
            tip='只能上传图片信息'
            onChange={(value: string) => setFileUrl(value)}
          />
        )}
        {type == 'url' && (
          <Input.TextArea value={url} onChange={setUrl} placeholder="请输入URL地址" />
        )}

        <div className="flex mt-8 justify-end">
          <Space>
            <Button onClick={() => props.onClose()}>取消</Button>
            <Button onClick={() => {
                if(type == 'file') props.onSubmit(fileUrl)
                else props.onSubmit(url);
            }} type="primary">确认</Button>
          </Space>
        </div>
      </div>
  )
}

export default CustomUpload;