import React from 'react';
import { Modal } from '@arco-design/web-react';
import ajax from 'ajax';
import { action, observable, makeObservable } from "mobx";
import CustomUpload from './component/CustomUpload';

class Store {
    mdEditor: any;

    @observable value = "";
    @action
    setValue = (val) => {
        this.value = val;
    }

    handleEditorChange = (it, event) => {
        this.setValue(it.text);
    };

    handleImageUpload = (file) => {
        const formData = new FormData();
        formData.append('image', file);
        return ajax.post(
            '/upload-img',
            formData,
        ).then((res) =>{
            return res.data.url
        })
    };

    onCustomImageUpload = (event): Promise<{
        url: string;
        text?: string;
    }> => {
        return new Promise((resolve, reject) => {
        //   const result = window.prompt('Please enter image url here...');
        //   resolve({ url: result });
            const result = Modal.info({
                icon: null,
                title: null,
                style: { width: 600 },
                content: React.createElement(CustomUpload, {
                    onClose: () => result.close(),
                    onSubmit: (url) => {
                        result.close();
                        resolve({ url })
                    }
                }),
                onCancel: () => {
                    reject();
                },
                hideCancel: false,
                footer: null,
            })
        });
    };

    handleGetMdValue = () => {
        if (this.mdEditor) {
          alert(this.mdEditor.getMdValue());
        }
    };

    handleGetHtmlValue = () => {
        if (this.mdEditor) {
          alert(this.mdEditor.getHtmlValue());
        }
    };

    handleSetValue = () => {
        const text = window.prompt('Content');
        this.setValue(text);
    };

    constructor() {
        makeObservable(this);
    }
}

export default Store;